#include "stdlib/math/base/special/expm1f.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/constants/float32/exponent_bias.h"
#include <stdint.h>

static const float one = 1.0f;
static const float tiny = 1.0e-30f;
static const float o_threshold = 8.8721679688e+01f;  /* 0x42b17180 */
static const float ln2_hi = 6.9313812256e-01f;       /* 0x3f317180 */
static const float ln2_lo = 9.0580006145e-06f;       /* 0x3717f7d1 */
static const float invln2 = 1.4426950216e+00f;       /* 0x3fb8aa3b */
static const float Q1 = -3.3333212137e-02f;          /* -0x888868.0p-28 */
static const float Q2 = 1.5807170421e-03f;           /*  0xcf3010.0p-33 */

static volatile float huge_val = 1.0e+30f;

/**
* Computes `exp(x) - 1` for a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_expm1f( 0.2f );
* // returns ~0.221f
*/
float stdlib_base_expm1f( const float x ) {
	float y;
	float hi;
	float lo;
	float c;
	float t;
	float e;
	float hxs;
	float hfx;
	float r1;
	float twopk;
	float xv;
	int32_t k;
	int32_t xsb;
	uint32_t hx;

	xv = x;
	stdlib_base_float32_to_word( xv, &hx );
	xsb = hx & 0x80000000;             /* sign bit of x */
	hx &= 0x7fffffff;                  /* high word of |x| */

	// Filter out huge and non-finite arguments...
	if ( hx >= 0x4195b844 ) {           /* if |x|>=27*ln2 */
		if ( hx >= 0x42b17218 ) {       /* if |x|>=88.721... */
			if ( hx > 0x7f800000 ) {
				return xv + xv;
			}
			if ( hx == 0x7f800000 ) {
				return ( xsb == 0 ) ? xv : -1.0f; /* exp(+-inf)={inf,-1} */
			}
			if ( xv > o_threshold ) {
				return huge_val * huge_val; /* overflow */
			}
		}
		if ( xsb != 0 ) {
			return tiny - one;
		}
	}

	c = 0.0f;

	// Argument reduction...
	if ( hx > 0x3eb17218 ) {           /* if |x| > 0.5 ln2 */
		if ( hx < 0x3F851592 ) {       /* and |x| < 1.5 ln2 */
			if ( xsb == 0 ) {
				hi = xv - ln2_hi;
				lo = ln2_lo;
				k = 1;
			} else {
				hi = xv + ln2_hi;
				lo = -ln2_lo;
				k = -1;
			}
		} else {
			k = (int32_t)( invln2 * xv + ( ( xsb == 0 ) ? 0.5f : -0.5f ) );
			t = (float)k;
			hi = xv - t * ln2_hi;      /* t*ln2_hi is exact here */
			lo = t * ln2_lo;
		}
		xv = hi - lo;
		c = ( hi - xv ) - lo;
	} else if ( hx < 0x33000000 ) {     /* when |x|<2**-25, return x */
		t = huge_val + xv;              /* return x with inexact flags when x!=0 */
		return xv - ( t - ( huge_val + xv ) );
	} else {
		k = 0;
	}

	// x is now in primary range...
	hfx = 0.5f * xv;
	hxs = xv * hfx;
	r1 = one + hxs * ( Q1 + hxs * Q2 );
	t = 3.0f - r1 * hfx;
	e = hxs * ( ( r1 - t ) / ( 6.0f - xv * t ) );
	if ( k == 0 ) {
		return xv - ( xv * e - hxs );  /* c is 0 */
	}
	stdlib_base_float32_from_word( ( (uint32_t)( STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS + k ) ) << 23, &twopk ); /* 2^k */
	e = ( xv * ( e - c ) ) - c;
	e -= hxs;
	if ( k == -1 ) {
		return 0.5f * ( xv - e ) - 0.5f;
	}
	if ( k == 1 ) {
		if ( xv < -0.25f ) {
			return -2.0f * ( e - ( xv + 0.5f ) );
		}
		return one + 2.0f * ( xv - e );
	}
	if ( k <= -2 || k > 56 ) {         /* suffice to return exp(x)-1 */
		y = one - ( e - xv );
		if ( k == 128 ) {
			y = y * 2.0f * 1.7014118346046923e+38f; /* 0x1p127F */
		} else {
			y = y * twopk;
		}
		return y - one;
	}
	t = one;
	if ( k < 23 ) {
		stdlib_base_float32_from_word( (uint32_t)0x3f800000 - ( (uint32_t)0x1000000 >> (uint32_t)k ), &t ); /* t=1-2^-k */
		y = t - ( e - xv );
		y = y * twopk;
	} else {
		stdlib_base_float32_from_word( ( (uint32_t)( STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS - k ) ) << 23, &t ); /* 2^-k */
		y = xv - ( e + t );
		y += one;
		y = y * twopk;
	}
	return y;
}
